        for box in containedBoxes[current_box]:
            if box not in accessible:
                accessible.add(box)
                queue.append(box)
        # Add keys to accessible set
        for key_box in keys[current_box]:
            if status[key_box] == 1 or key_box in accessible:
                accessible.add(key_box)
